package com.bank.grpc;

import java.util.logging.Logger;

// Documents the compatibility guarantees enforced in CI (e.g. with `buf breaking`).
public class VersioningNotes {
    private static final Logger log = Logger.getLogger(VersioningNotes.class.getName());

    public static void main(String[] args) {
        log.info("SAFE changes (backward + forward compatible):");
        log.info(" - add new field with a NEW unused number (optional)");
        log.info(" - add new RPC method (ScheduledTransfer)");
        log.info(" - add a new service or a new package version bank.v2");
        log.info("UNSAFE changes (break existing clients):");
        log.info(" - change or REUSE an existing field number");
        log.info(" - change a field's TYPE (int32 -> string)");
        log.info(" - REMOVE a field clients still read (reserve it instead)");
        log.info(" - rename a field used by JSON mapping");
        log.info("For a truly breaking redesign: create bank.v2.AccountService "
               + "and run v1 and v2 side by side, migrate clients gradually.");
    }
}
